parameters.jsCode:
// Filter tasks for Claude Code
const tasks = $input.first().json.tasks || [];
const claudeTasks = tasks.filter(task => 
  task.action === 'claude' || 
  task.type === 'feature' ||
  (task.type === 'ui' && task.priority === 'high')
);

// Group related tasks
const groupedTasks = {};
claudeTasks.forEach(task => {
  const key = task.component || 'general';
  if (!groupedTasks[key]) {
    groupedTasks[key] = [];
  }
  groupedTasks[key].push(task);
});

return Object.entries(groupedTasks).map(([component, tasks]) => ({
  component: component,
  tasks: tasks,
  chatId: $input.first().json.chatId,
  timestamp: new Date().toISOString()
}));

// Format tasks into Claude Code prompt
const data = $input.first().json;
const tasks = data.tasks;

let prompt = `# Development Tasks for ${data.component}

`;
prompt += `Generated: ${data.timestamp}

`;

tasks.forEach((task, index) => {
  prompt += `## Task ${index + 1}: ${task.title}

`;
  prompt += `**Type**: ${task.type}\n`;
  prompt += `**Priority**: ${task.priority}\n\n`;
  prompt += `### Description\n${task.description}\n\n`;

  // Add implementation hints based on type
  if (task.type === 'bug') {
    prompt += `### Debugging Steps\n`;
    prompt += `1. Locate the ${task.component} component\n`;
    prompt += `2. Identify the issue described\n`;
    prompt += `3. Fix and test the solution\n\n`;
  } else if (task.type === 'feature') {
    prompt += `### Implementation Requirements\n`;
    prompt += `1. Add to ${task.component}\n`;
    prompt += `2. Follow existing patterns\n`;
    prompt += `3. Add necessary types and validation\n\n`;
  } else if (task.type === 'ui') {
    prompt += `### UI Requirements\n`;
    prompt += `1. Update ${task.component} styling\n`;
    prompt += `2. Ensure responsive design\n`;
    prompt += `3. Follow SISO brand guidelines (orange/yellow theme)\n\n`;
  }
});

prompt += `### Instructions\n`;
prompt += `1. Implement all tasks listed above\n`;
prompt += `2. Run lint and build checks\n`;
prompt += `3. Test thoroughly\n`;
prompt += `4. Commit with descriptive message\n`;

return {
  filename: `claude-tasks-${data.component}-${Date.now()}.md`,
  content: prompt,
  chatId: data.chatId,
  taskCount: tasks.length,
  component: data.component
};

